class Node {
  int value;
  Node? left, right;
  Node(this.value);
}

Node? insert(Node? n, int v) {
  if (n == null) return Node(v);
  if (v < n.value) {
    n.left = insert(n.left, v);
  } else if (v > n.value) {
    n.right = insert(n.right, v);
  }
  return n;
}

List<int> inOrder(Node? n) =>
    n == null ? [] : [...inOrder(n.left), n.value, ...inOrder(n.right)];

Node? delete(Node? n, int v) {
  if (n == null) return null;
  if (v < n.value) {
    n.left = delete(n.left, v);
  } else if (v > n.value) {
    n.right = delete(n.right, v);
  } else {
    if (n.left == null) return n.right;
    if (n.right == null) return n.left;
    var s = n.right!;
    while (s.left != null) {
      s = s.left!;
    }
    n.value = s.value;
    n.right = delete(n.right, s.value);
  }
  return n;
}

void main() {
  Node? root;
  for (final v in [50, 30, 70, 60, 80]) {
    root = insert(root, v);
  }
  root = delete(root, 50);
  print(root!.value);
  print(inOrder(root));
}
