class N {
  final int v;
  final N? left, right;
  const N(this.v, [this.left, this.right]);
}

bool isBst(N? n, [int? min, int? max]) {
  if (n == null) return true;
  if ((min != null && n.v <= min) || (max != null && n.v >= max)) return false;
  return isBst(n.left, min, n.v) && isBst(n.right, n.v, max);
}

