class N {
  final int v;
  final N? left, right;
  const N(this.v, [this.left, this.right]);
}

int? ceil(N? n, int x) {
  int? best;
  while (n != null) {
    if (n.v == x) return x;
    if (n.v > x) {
      best = n.v;
      n = n.left;
    } else {
      n = n.right;
    }
  }
  return best;
}

void main() {
  const t = N(8, N(3, N(1), N(6)), N(10, null, N(14)));
  print(ceil(t, 7));
  print(ceil(t, 15));
